CREATE COLUMN TABLE "TEST_AP"."ACFP" ("ID" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(6) NOT NULL , "Descrip" NCLOB MEMORY THRESHOLD 1000, "App" NCLOB MEMORY THRESHOLD 1000, "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" NVARCHAR(6), "LogInstanc" INTEGER CS_INT NOT NULL , "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("ID", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ACFP_CFOP_CODE" ON "TEST_AP"."ACFP" ( "Code" ASC, "LogInstanc" ASC )